create or replace function public.conik_get_subscription_status(p_organization_id uuid) returns table(active boolean,plan_code text,starts_at timestamptz,ends_at timestamptz,whatsapp_active boolean,whatsapp_starts_at timestamptz,whatsapp_ends_at timestamptz) language plpgsql security definer set search_path=public as $$ declare c public.conik_subscriptions%rowtype; w public.whatsapp_subscriptions%rowtype; begin if not exists(select 1 from public.organization_members where organization_id=p_organization_id and user_id=auth.uid()) then raise exception 'FORBIDDEN'; end if; select * into c from public.conik_subscriptions where organization_id=p_organization_id and status='active' order by ends_at desc limit 1; select * into w from public.whatsapp_subscriptions where organization_id=p_organization_id and status='active' order by ends_at desc limit 1; return query select coalesce(c.ends_at>now(),false),c.plan_code,c.starts_at,c.ends_at,coalesce(w.ends_at>now(),false),w.starts_at,w.ends_at; end; $$;
revoke all on function public.conik_get_subscription_status(uuid) from public; grant execute on function public.conik_get_subscription_status(uuid) to authenticated;
create or replace function public.whatsapp_subscription_active(p_organization_id uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.whatsapp_subscriptions where organization_id=p_organization_id and provider='green-api' and status='active' and starts_at<=now() and ends_at>now()); $$;
revoke all on function public.whatsapp_subscription_active(uuid) from public; grant execute on function public.whatsapp_subscription_active(uuid) to authenticated;
create or replace function public.whatsapp_purchase_or_renew(p_organization_id uuid,p_user_id uuid,p_plan_code text,p_days integer,p_daily_price numeric,p_amount numeric,p_currency text default 'XOF',p_instance_id uuid default null,p_order_id uuid default null,p_payment_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; e public.whatsapp_subscriptions%rowtype; s timestamptz; f timestamptz; begin if p_user_id<>auth.uid() then raise exception 'FORBIDDEN'; end if; if not exists(select 1 from public.organization_members where organization_id=p_organization_id and user_id=auth.uid() and role in('owner','admin')) then raise exception 'FORBIDDEN'; end if; if p_plan_code not in('basic','premium') or p_days not between 1 and 31 or p_daily_price<0 or p_amount<0 then raise exception 'INVALID_WHATSAPP_SUBSCRIPTION'; end if; if p_payment_id is null or not exists(select 1 from public.payments where id=p_payment_id and order_id=p_order_id and status='paid') then raise exception 'PAYMENT_NOT_CONFIRMED'; end if; select * into e from public.whatsapp_subscriptions where organization_id=p_organization_id and provider='green-api' and status='active' and ends_at>now() order by ends_at desc limit 1 for update; if found then s:=e.starts_at; f:=e.ends_at+make_interval(days=>p_days); update public.whatsapp_subscriptions set ends_at=f,days_purchased=days_purchased+p_days,amount=amount+p_amount,plan_code=p_plan_code,payment_id=p_payment_id,order_id=p_order_id,instance_id=coalesce(p_instance_id,instance_id),updated_at=now() where id=e.id returning id into v_id; else s:=now(); f:=s+make_interval(days=>p_days); insert into public.whatsapp_subscriptions(organization_id,user_id,plan_code,days_purchased,daily_price,amount,currency,starts_at,ends_at,status,payment_id,order_id,instance_id) values(p_organization_id,p_user_id,p_plan_code,p_days,p_daily_price,p_amount,p_currency,s,f,'active',p_payment_id,p_order_id,p_instance_id) returning id into v_id; end if; return v_id; end; $$;
revoke all on function public.whatsapp_purchase_or_renew(uuid,uuid,text,integer,numeric,numeric,text,uuid,uuid,uuid) from public; grant execute on function public.whatsapp_purchase_or_renew(uuid,uuid,text,integer,numeric,numeric,text,uuid,uuid,uuid) to authenticated;
create or replace function public.conik_purchase_or_renew(p_organization_id uuid,p_user_id uuid,p_plan_code text,p_amount numeric,p_currency text default 'XOF',p_order_id uuid default null,p_payment_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; e public.conik_subscriptions%rowtype; s timestamptz; f timestamptz; begin if p_user_id<>auth.uid() then raise exception 'FORBIDDEN'; end if; if not exists(select 1 from public.organization_members where organization_id=p_organization_id and user_id=auth.uid() and role in('owner','admin')) then raise exception 'FORBIDDEN'; end if; if p_plan_code not in('basic','premium') or p_amount<0 then raise exception 'INVALID_SUBSCRIPTION'; end if; if p_payment_id is null or not exists(select 1 from public.payments where id=p_payment_id and order_id=p_order_id and status='paid') then raise exception 'PAYMENT_NOT_CONFIRMED'; end if; select * into e from public.conik_subscriptions where organization_id=p_organization_id and status='active' and ends_at>now() order by ends_at desc limit 1 for update; if found then s:=e.starts_at; f:=e.ends_at+interval '30 days'; update public.conik_subscriptions set ends_at=f,amount=amount+p_amount,plan_code=p_plan_code,payment_id=p_payment_id,order_id=p_order_id,updated_at=now() where id=e.id returning id into v_id; else s:=now(); f:=s+interval '30 days'; insert into public.conik_subscriptions(organization_id,user_id,plan_code,duration_days,amount,currency,starts_at,ends_at,status,payment_id,order_id) values(p_organization_id,p_user_id,p_plan_code,30,p_amount,p_currency,s,f,'active',p_payment_id,p_order_id) returning id into v_id; end if; return v_id; end; $$;
revoke all on function public.conik_purchase_or_renew(uuid,uuid,text,numeric,text,uuid,uuid) from public; grant execute on function public.conik_purchase_or_renew(uuid,uuid,text,numeric,text,uuid,uuid) to authenticated;
create or replace function public.whatsapp_subscription_mark_expired() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.whatsapp_subscriptions set status='expired',updated_at=now() where status='active' and ends_at<=now(); get diagnostics n=row_count; return n; end; $$;
revoke all on function public.whatsapp_subscription_mark_expired() from public; grant execute on function public.whatsapp_subscription_mark_expired() to service_role;
create or replace function public.conik_subscription_mark_expired() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.conik_subscriptions set status='expired',updated_at=now() where status='active' and ends_at<=now(); get diagnostics n=row_count; return n; end; $$;
revoke all on function public.conik_subscription_mark_expired() from public; grant execute on function public.conik_subscription_mark_expired() to service_role;
